/**
 * O show de luzes do mar — porte de `componentes/viz/bioluz.js`.
 *
 * No escuro do fundo do oceano, a água-viva acende sozinha. É luz FRIA: quase
 * toda a energia vira luz e quase nada vira calor — o contrário de uma lâmpada
 * incandescente. E o brilho tem um ponto: fraco, o plâncton nem percebe; forte
 * demais, ele foge. No ponto certo, a presa vem.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import { type EstadoDaViz, infoDe, numeroDe, paleta, rodape, titulo } from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const bioluz: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  // Declarado ANTES do `criarCanvas2d`: o laço dispara já no primeiro quadro e
  // chama `desenhar`, que lê isto — embaixo, daria erro de zona morta temporal.
  const plancton = Array.from({ length: 26 }, () => ({
    a: Math.random() * Math.PI * 2,
    r: 0.4 + Math.random() * 0.6,
    vel: 0.3 + Math.random() * 0.5,
  }));

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const controle = Math.max(0, numeroDe(valores, 'b', 0)) / 100;
    const ok = info.ok === true;

    const cx = L / 2;
    const cy = A * 0.5;

    titulo(ctx, L, A, 'Luz sem calor, no ponto certo');

    // A água do fundo. Aqui a cena escurece de propósito, contra a regra das
    // outras: o assunto é uma luz vista no escuro, e num fundo claro não há
    // brilho nenhum para mostrar.
    const agua = ctx.createLinearGradient(0, A * 0.16, 0, A);
    agua.addColorStop(0, '#163a5e');
    agua.addColorStop(1, '#0a2138');
    ctx.fillStyle = agua;
    ctx.fillRect(0, A * 0.16, L, A * 0.84);

    const pulso = 0.85 + 0.15 * Math.sin(t * 2);
    const brilho = controle * pulso;
    const raio = Math.min(L, A) * 0.18;

    ctx.save();
    ctx.beginPath();
    ctx.rect(0, A * 0.16, L, A * 0.84);
    ctx.clip();

    ctx.globalCompositeOperation = 'lighter';
    const halo = ctx.createRadialGradient(cx, cy, 0, cx, cy, raio * 6);
    halo.addColorStop(0, `rgb(90 220 255 / ${(0.12 + 0.5 * brilho) * 100}%)`);
    halo.addColorStop(1, 'rgb(90 220 255 / 0%)');
    ctx.fillStyle = halo;
    ctx.fillRect(0, 0, L, A);
    ctx.globalCompositeOperation = 'source-over';

    // O plâncton se aproxima no brilho certo e recua quando é forte demais.
    for (const p of plancton) {
      const alvo = ok ? raio * 1.8 : controle > 0.85 ? raio * 7 : raio * 6.5;
      p.r += (alvo / raio - p.r) * 0.02;
      p.a += p.vel * 0.004;

      const x = cx + Math.cos(p.a) * p.r * raio;
      const y = cy + Math.sin(p.a) * p.r * raio * 0.8;
      ctx.fillStyle = ok ? '#b4ffd2' : '#96b4d2';
      ctx.beginPath();
      ctx.arc(x, y, 2, 0, Math.PI * 2);
      ctx.fill();
    }

    // O sino da água-viva.
    ctx.fillStyle = `rgb(190 240 255 / ${(0.72 + 0.2 * brilho) * 100}%)`;
    ctx.beginPath();
    ctx.ellipse(cx, cy, raio, raio * 0.85, 0, Math.PI, 0);
    ctx.fill();
    ctx.strokeStyle = `rgb(235 250 255 / ${(0.7 + 0.3 * brilho) * 100}%)`;
    ctx.lineWidth = 2.5;
    ctx.stroke();

    ctx.strokeStyle = `rgb(170 235 255 / ${(0.65 + 0.3 * brilho) * 100}%)`;
    ctx.lineWidth = 2;
    for (let i = -3; i <= 3; i++) {
      const x0 = cx + i * raio * 0.22;
      ctx.beginPath();
      ctx.moveTo(x0, cy);
      for (let s = 0; s <= raio * 1.6; s += 6) {
        ctx.lineTo(x0 + Math.sin(s * 0.1 + t * 3 + i) * 4, cy + s);
      }
      ctx.stroke();
    }

    ctx.restore();

    rodape(
      ctx,
      L,
      A,
      ok,
      'Luz fria no ponto: o plâncton se aproxima ✔',
      `Brilho ${Math.round(controle * 100)}% — ajuste a luz fria.`,
      cor.fraco,
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default bioluz;
